data class Expense(val category: String, val amount: Double)
fun main() {
    val expenses = listOf(
        Expense("Food", 5.0),
        Expense("Travel", 8.0),
        Expense("Food", 3.0),
    )
    val totals = expenses.groupBy { it.category }
        .mapValues { (_, items) -> items.sumOf { it.amount } }
    println(totals)
}
